<script setup lang="ts">
import {ref} from 'vue'; import {useRouter} from 'vue-router'; import {api, describe, saveSession, session} from '../api'; import type {User} from '../types'
const router=useRouter(), base=ref(session.base), key=ref(''), error=ref(''), busy=ref(false)
async function connect(){ error.value=''; busy.value=true; const previous=session.base; try { const url=new URL(base.value); if(!['http:','https:'].includes(url.protocol)||url.username||url.password||url.search||url.hash) throw new Error(); session.base=url.toString().replace(/\/$/,''); const user=await api<User>('/api/users/me',{headers:{Authorization:`Bearer ${key.value.trim()}`}},false); saveSession(session.base,key.value.trim(),user); key.value=''; await router.push('/projects') } catch(e){session.base=previous; error.value=e instanceof TypeError || !(e instanceof Error) || e.message === '' ? '请输入有效的后端 HTTP 地址' : describe(e)} finally {busy.value=false} }
</script>
<template><div class="connect-wrap"><div class="intro"><p class="eyebrow">AGILE AGENT WORKSPACE</p><h1>让会议结论，<br>真正开始行动。</h1><p>从会议记录出发，提取任务草稿，经人工确认后进入项目工作流。</p><div class="flow"><span>01 会议记录</span><span>02 AI 草稿</span><span>03 人工确认</span><span>04 正式任务</span></div></div><section class="card connect-card"><p class="eyebrow">开始使用</p><h2>连接后端</h2><p class="muted">使用已有的 API Key 连接你的项目空间。</p><form @submit.prevent="connect"><label>API Base URL<input v-model.trim="base" type="url" required placeholder="http://localhost:8080"></label><label>API Key<input v-model="key" type="password" autocomplete="off" required placeholder="请输入 API Key"></label><p class="notice">当前为本地演示凭证模式，API Key 不应作为生产网页登录方案。凭证仅保存在当前标签页的会话中。</p><p v-if="error" class="error" role="alert">{{error}}</p><button class="primary wide" :disabled="busy">{{busy?'正在连接…':'验证并进入'}}</button></form></section></div></template>
